"""food-picture-01 round 2: "Tonkotsu, perfected — the noodle pull".

One hero dish, shot to make the viewer hungry: a steaming bowl of
tonkotsu ramen, wooden chopsticks lifting a tall glossy noodle pull,
a halved jammy egg with a dripping yolk, chashu, nori and spring
onions in a speckled dark bowl, against a dark moody background
with warm bokeh and visible steam.

The program is deterministic and offline: it writes the embedded
image byte-identical to /output/entry.png (Python 3.13 stdlib only).
Run locally with MAKEFUN_OUTPUT_DIR=out python3 main.py.
"""

import base64
import os

# The image, base64-encoded (a 1024x1024 JPEG, 247,829 bytes).
DATA = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(base64.b64decode(DATA))


if __name__ == "__main__":
    main()
